def create_more_activity_modules(apps, schema_editor):
    ActivityModuleTemplate = apps.get_model("teumteum", "ActivityModuleTemplate")

    for entry in ENTRIES:
        ActivityModuleTemplate.objects.create(**entry)


def remove_more_activity_modules(apps, schema_editor):
    ActivityModuleTemplate = apps.get_model("teumteum", "ActivityModuleTemplate")
    titles = [entry["title"] for entry in ENTRIES]
    ActivityModuleTemplate.objects.filter(title__in=titles).delete()


